				T mapping = new T();
				mapping.SetDefaultKeys(type, KeyPresetType.WasdKeys);
				mappings.Add(mapping);
			}
			if(defaultMappings.HasFlag(DefaultKeyMappingType.ArrowKeys)) {
				T mapping = new T();
				mapping.SetDefaultKeys(type, KeyPresetType.ArrowKeys);
				mappings.Add(mapping);
			}

