					if(i < switchPath.Length - 1) {
						cfg = property.GetValue(cfg);
						if(cfg == null) {
							//Invalid
							return false;
						}
					} else {
						return ApplySetting(cfg, property, switchValue);
					}
				}
			}

			return false;
		}

